"""Join complete Markdown blocks without changing retained or generated bytes."""


def assemble_blocks(parts: list[tuple[str, bool]], *, newline: str, separate=False) -> str:
    """Only add separators at seams involving an edited block.

    Whitespace gaps belong to the captured page and stay verbatim. Two missing
    line breaks separate paragraphs/code; a comment can additionally separate
    adjacent literal blocks that Markdown would otherwise coalesce.
    """
    result = []
    tail = ""
    previous_edited = False
    have_block = False
    for text, edited in parts:
        if not text.strip():
            result.append(text)
            tail += text
            previous_edited |= edited
            continue
        if have_block and (previous_edited or edited):
            leading = text[: len(text) - len(text.lstrip())]
            count = tail.count("\n") + leading.count("\n")
            if separate:
                result.append(newline * max(0, 2 - tail.count("\n")) + "<!-- -->" + newline * 2)
            elif count < 2:
                result.append(newline * (2 - count))
        result.append(text)
        tail = text[len(text.rstrip()) :]
        previous_edited = edited
        have_block = True
    return "".join(result)
